import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func testFixedAssistantPortraitPhysicalKeyboardAskAndControlledResponse() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();tap(app,"Profile, tab, 5 of 5");tap(app,"Ask Fancy");tap(app,"Start conversation");let q=app.textViews["Ask Fancy a question"];XCTAssertTrue(q.waitForExistence(timeout:12),app.debugDescription);q.tap();for c in "Please draft my application."{q.typeText(String(c));Thread.sleep(forTimeInterval:0.15)};let keyboard=app.keyboards.firstMatch;XCTAssertTrue(keyboard.waitForExistence(timeout:10));let ask=app.buttons["Ask"],close=app.buttons["Close"];print("QA_NATIVE81_KEYBOARD keyboard=\(keyboard.frame) question=\(q.frame) ask=\(ask.frame) close=\(close.frame) questionHittable=\(q.isHittable) askHittable=\(ask.isHittable)\n"+app.debugDescription);let geometry=XCTAttachment(screenshot:app.screenshot());geometry.name="native81-f49-portrait-keyboard-reachable";geometry.lifetime = .keepAlways;add(geometry);XCTAssertTrue(q.isHittable);XCTAssertTrue(ask.isHittable);XCTAssertTrue(close.isHittable);XCTAssertLessThanOrEqual(q.frame.maxY,keyboard.frame.minY+1);XCTAssertLessThanOrEqual(ask.frame.maxY,keyboard.frame.minY+1);XCTAssertTrue(app.frame.contains(close.frame));ask.tap();let response=app.staticTexts.matching(NSPredicate(format:"label BEGINSWITH %@","Please confirm the date, area, budget or exact meal")).firstMatch;XCTAssertTrue(response.waitForExistence(timeout:20),app.debugDescription);XCTAssertFalse(app.buttons["Retry assistant request"].exists);print("QA_NATIVE81_CONTROLLED_REPLY\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native81-f49-controlled-response";a.lifetime = .keepAlways;add(a);tap(app,"Close")
 }
}
